style.css:
@-moz-document domain("roblox.com") {
/* 1. USTAWIENIE TŁA */
    body, .dark-theme, .light-theme, #container-main {
        background-image: url("https://redd.it") !important;
        background-size: cover !important;
        background-attachment: fixed !important;
        background-position: center top !important;
        background-repeat: no-repeat !important;
    }

    /* 2. EFEKT CZARNO-BIAŁY I PRZYCIEMNIENIE */
    body::before {
        content: "";
        position: fixed;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background: inherit;
        filter: grayscale(100%) brightness(45%); /* 100% czarno-białe, przyciemnione dla czytelności */
        z-index: -1;
    }

    /* 3. PRZEZROCZYSTOŚĆ INTERFEJSU */
    .container-main, 
    .section-content, 
    .rbx-header,
    .content,
    .left-col-list,
    .place-container,
    .stack .card-list .card-item {
        background: rgba(0, 0, 0, 0.5) !important; /* Półprzezroczyste panele */
        border: none !important;
        border-radius: 12px !important; /* Ładne zaokrąglenia */
    }

    /* 4. CZYSZCZENIE STRONY */
    .ad-container, .abp, #AdvertisingLeaderboard, .footer-note {
        display: none !important; /* Ukrywa reklamy i zbędne napisy */
    }

    /* Usunięcie tła pod kafelkami gier */
    .game-card-container, .item-card-container {
        background: transparent !important;
    }

    /* Biały tekst dla lepszej widoczności */
    .text-title, .text-name, .text-robux-lg {
        color: #ffffff !important;
    }
}
